const base = String($env.SITE_BASE_URL || '').trim().replace(/\/+$/, '');
const expectedEnv = String($env.SITE_EXPECTED_ENV || '').trim();
if (!/^https:\/\/[^/\s]+$/.test(base) && !/^http:\/\/localhost(:\d+)?$/.test(base)) throw new Error('SITE_BASE_URL must be an https origin (scheme and host only, no path)');
if (expectedEnv !== 'production' && expectedEnv !== 'staging') throw new Error('SITE_EXPECTED_ENV must be production or staging');

const checks = [
  { id: 'home', path: '/', type: 'page' },
  { id: 'locations', path: '/locations/', type: 'page' },
  { id: 'referral', path: '/referral/', type: 'page' },
  { id: 'contact', path: '/contact-us/', type: 'page' },
  { id: 'robots-txt', path: '/robots.txt', type: 'robots' },
  { id: 'sitemap', path: '/sitemap.xml', type: 'sitemap' },
  { id: 'api-index', path: '/api/v1/index.json', type: 'api' },
];
return checks.map((c) => ({ json: { ...c, url: base + c.path, expectedEnv } }));

// Failure rules follow packages/automation/src/monitoring.ts:
//   - evaluateUptime: a check fails on a timeout or an unexpected status; alert after MIN_CONSECUTIVE (2) failures in a row, to avoid flapping
//   - evaluateVitals: any 5xx is critical and alerts at once
//   - shouldNotify: no repeat notification for the same check inside COOLDOWN_MINUTES (60); at exactly 60 minutes it notifies again
// Added here: environment mismatches (production page noindex, staging page indexable, wrong API environment) are critical and alert at once.
const MIN_CONSECUTIVE = 2;
const COOLDOWN_MINUTES = 60;
const nowMs = Date.now();

const checks = $('Build check list').all().map((i) => i.json);
const results = $input.all().map((i) => i.json);
const state = $getWorkflowStaticData('global');
state.failures = state.failures || {};
state.lastNotified = state.lastNotified || {};

const bodyText = (r) => {
  const b = r.body;
  if (typeof b === 'string') return b;
  if (b && typeof b === 'object' && typeof b.data === 'string') return b.data;
  return null;
};
const header = (r, name) => {
  const h = r.headers || {};
  const key = Object.keys(h).find((k) => k.toLowerCase() === name);
  const v = key ? h[key] : '';
  return Array.isArray(v) ? v.join(',') : String(v || '');
};

const alerts = [];
const summary = [];
checks.forEach((c, idx) => {
  const r = results[idx] || {};
  const sc = Number(r.statusCode);
  const status = r.statusCode === undefined || r.statusCode === null || !Number.isFinite(sc) ? null : sc;
  const text = bodyText(r);
  const problems = [];
  let critical = false;
  const expectStatus = c.type === 'sitemap' && c.expectedEnv === 'staging' ? 404 : 200;

  if (status === null) problems.push('no_response_or_timeout');
  else if (status !== expectStatus) {
    problems.push('unexpected_status_' + status + '_expected_' + expectStatus);
    if (status >= 500 && status <= 599) critical = true;
    if (c.type === 'sitemap' && c.expectedEnv === 'staging' && status === 200) critical = true; // staging must not publish a sitemap
  }

  if (status === expectStatus && c.type === 'api') {
    let json = null;
    if (text !== null) {
      try { json = JSON.parse(text); } catch (e) { json = null; }
    } else if (r.body && typeof r.body === 'object') {
      json = r.body; // already parsed by the HTTP node, so it was valid JSON
    }
    if (json === null || typeof json !== 'object') problems.push('api_index_is_not_valid_json');
    else {
      if (json.apiVersion !== '1') problems.push('api_version_not_1');
      if (json.environment !== c.expectedEnv) { problems.push('api_environment_is_' + json.environment + '_expected_' + c.expectedEnv); critical = true; }
    }
    if (!/\bnoindex\b/i.test(header(r, 'x-robots-tag'))) problems.push('api_response_is_missing_noindex');
  } else if (status === expectStatus && text === null) {
    problems.push('response_body_unreadable');
  } else if (status === expectStatus && c.type === 'page') {
    const headerNoindex = /\bnoindex\b/i.test(header(r, 'x-robots-tag'));
    const metaMatch = text.match(/<meta[^>]+name=["']robots["'][^>]*>/i);
    const metaNoindex = metaMatch ? /\bnoindex\b/i.test(metaMatch[0]) : false;
    if (c.expectedEnv === 'production' && (headerNoindex || metaNoindex)) { problems.push('production_page_is_noindex'); critical = true; }
    if (c.expectedEnv === 'staging' && !(headerNoindex && metaNoindex)) {
      problems.push('staging_page_missing_noindex_' + [!headerNoindex && 'header', !metaNoindex && 'meta'].filter(Boolean).join('_and_'));
      critical = true;
    }
  } else if (status === expectStatus && c.type === 'robots') {
    const starGroup = text.split(/\n\s*\n/).find((g) => /^user-agent:\s*\*\s*$/im.test(g)) || '';
    const blocksAll = /^disallow:\s*\/\s*$/im.test(starGroup);
    if (c.expectedEnv === 'production' && (blocksAll || !/^sitemap:/im.test(text))) { problems.push(blocksAll ? 'production_robots_blocks_everything' : 'production_robots_has_no_sitemap_line'); critical = true; }
    if (c.expectedEnv === 'staging' && !blocksAll) { problems.push('staging_robots_does_not_block_everything'); critical = true; }
  } else if (status === expectStatus && c.type === 'sitemap') {
    if (c.expectedEnv === 'production' && text.indexOf('<urlset') < 0) problems.push('production_sitemap_is_not_a_urlset');
  }

  if (problems.length === 0) {
    state.failures[c.id] = 0;
    summary.push(c.id + ': ok');
    return;
  }
  state.failures[c.id] = (state.failures[c.id] || 0) + 1;
  summary.push(c.id + ': ' + problems.join(', '));
  const due = critical || state.failures[c.id] >= MIN_CONSECUTIVE;
  const last = state.lastNotified[c.id];
  const cooledDown = !last || nowMs - last >= COOLDOWN_MINUTES * 60000;
  if (due && cooledDown) {
    state.lastNotified[c.id] = nowMs;
    alerts.push({ id: c.id, path: c.path, severity: critical ? 'critical' : 'warning', consecutiveFailures: state.failures[c.id], problems });
  }
});

return [{
  json: {
    hasAlerts: alerts.length > 0,
    alerts,
    checked: checks.length,
    summary,
    notifySubject: 'Site health: ' + alerts.length + ' check(s) failing' + (alerts.some((a) => a.severity === 'critical') ? ' (critical)' : ''),
    notifyText: [
      'These site checks are failing:',
      ...alerts.map((a) => '- ' + a.id + ' ' + a.path + ' [' + a.severity + ', ' + a.consecutiveFailures + ' in a row]: ' + a.problems.join(', ')),
      '',
      'A 5xx status or an environment mismatch (indexing rules, wrong environment) alerts at once. Other failures alert after ' + MIN_CONSECUTIVE + ' in a row. The same check is not reported again for ' + COOLDOWN_MINUTES + ' minutes.',
    ].join('\n'),
  },
}];
